"""Verify authored phased-array aperture, wavelength, delay and encoder identities."""

import json
from pathlib import Path

from matintegrity.models.phased_array import (
    PhasedArrayExamination,
    phased_array_acquisition_summary,
)

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "validation/phased_array_math.json"
EVIDENCE = {
    "source_id": "authored-paut-validation",
    "origin": "synthetic",
    "citation": "independent synthetic verification generated by this project",
}


def main():
    common_frame = {
        "sample_count": 1024,
        "sample_interval_s": 1.0e-8,
        "transmit_event_count": 1,
        "receive_channel_count": 4,
        "amplitude_encoding": "signed-int16",
        "time_zero_basis": "authored acquisition clock",
        "beam_law_id": "law-a",
    }
    examination = PhasedArrayExamination.model_validate(
        {
            "examination_id": "authored-paut",
            "procedure_id": "authored-procedure",
            "procedure_revision": "1",
            "physical_scope_id": "authored-weld",
            "material_condition_id": "authored-material",
            "acquisition_mode": "sectorial",
            "specimen_wave_velocity_m_s": 5900.0,
            "specimen_wave_velocity_basis": "authored basis",
            "encoder_id": "authored-encoder",
            "encoder_direction": "increasing",
            "probes": [
                {
                    "probe_id": "probe-a",
                    "role": "pulse_echo",
                    "element_count": 4,
                    "element_pitch_m": 0.001,
                    "element_width_m": 0.0008,
                    "center_frequency_Hz": 5.0e6,
                    "element_layout_basis": "authored layout",
                    "evidence": [EVIDENCE],
                }
            ],
            "wedges": [
                {
                    "wedge_id": "wedge-a",
                    "probe_id": "probe-a",
                    "wedge_material_id": "authored-polymer",
                    "wedge_longitudinal_velocity_m_s": 2300.0,
                    "nominal_exit_point_offset_m": 0.01,
                    "mounting_orientation": "authored orientation",
                    "evidence": [EVIDENCE],
                }
            ],
            "beam_laws": [
                {
                    "law_id": "law-a",
                    "transmit_probe_id": "probe-a",
                    "receive_probe_id": "probe-a",
                    "refracted_angle_rad": 0.7,
                    "refracted_wave_mode": "longitudinal",
                    "focus_distance_m": 0.02,
                    "first_transmit_element": 0,
                    "transmit_element_count": 4,
                    "transmit_delay_s": [0.0, 1.0e-8, 2.0e-8, 3.0e-8],
                    "first_receive_element": 0,
                    "receive_element_count": 4,
                    "receive_delay_s": [0.0, 1.0e-8, 2.0e-8, 3.0e-8],
                    "law_generation_basis": "authored focal law",
                }
            ],
            "frames": [
                {**common_frame, "frame_id": "f0", "encoder_position_m": 0.0, "data_sha256": "a" * 64},
                {**common_frame, "frame_id": "f1", "encoder_position_m": 0.001, "data_sha256": "b" * 64},
                {**common_frame, "frame_id": "f2", "encoder_position_m": 0.003, "data_sha256": "c" * 64},
            ],
            "indications": [],
            "probe_and_wedge_identity_reviewed": True,
            "material_velocity_reviewed": True,
            "beam_law_reviewed": True,
            "encoder_calibration_reviewed": True,
            "acquisition_calibration_reviewed": True,
            "frame_identity_reviewed": True,
            "indication_mapping_reviewed": True,
            "negative_result_reviewed": True,
            "evidence": [EVIDENCE],
        }
    )
    result = phased_array_acquisition_summary(examination)
    probe = result.values["probe_geometry_by_id"]["probe-a"]
    expected = {
        "physical_aperture_m": 0.0038,
        "nominal_specimen_wavelength_m": 5900.0 / 5.0e6,
        "pitch_to_nominal_wavelength_ratio": 0.001 / (5900.0 / 5.0e6),
        "transmit_delay_span_s": 3.0e-8,
        "encoder_span_m": 0.003,
        "minimum_nonzero_encoder_increment_m": 0.001,
        "maximum_nonzero_encoder_increment_m": 0.002,
    }
    computed = {
        **probe,
        "transmit_delay_span_s": result.values["beam_law_delay_span_by_id"]["law-a"]["transmit_delay_span_s"],
        "encoder_span_m": result.values["encoder_span_m"],
        "minimum_nonzero_encoder_increment_m": result.values["minimum_nonzero_encoder_increment_m"],
        "maximum_nonzero_encoder_increment_m": result.values["maximum_nonzero_encoder_increment_m"],
    }
    if result.status != "computed" or any(
        abs(computed[key] - value) > 1e-15 for key, value in expected.items()
    ):
        raise ValueError("phased-array arithmetic identity failed")
    report = {
        "schema": "matintegrity.phased_array_math.v1",
        "expected": expected,
        "computed": computed,
        "qualification": (
            "Synthetic acquisition-geometry and contract verification only; no probe field, wedge, focal law, "
            "encoder, waveform, reconstruction, indication detection, sizing or acceptance is qualified."
        ),
    }
    OUTPUT.write_text(json.dumps(report, indent=2), encoding="utf-8")
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()
